import React, { useState } from 'react';
import axios            from 'axios';
import { useNavigate }  from 'react-router-dom';

export default function CreateDeliveryForm() {
  const [f, setF] = useState({ customerId:'', address:'', status:'Pending' });
  const nav = useNavigate();

  const submit = async (e:any)=>{
    e.preventDefault();
    await axios.post(`${process.env.REACT_APP_API_URL}/api/delivery`, f);
    nav('/');
  };

  return (
    <form onSubmit={submit} style={{padding:20,maxWidth:400,margin:'auto'}}>
      <h3>New Delivery</h3>
      <input placeholder="Customer ID" value={f.customerId}
             onChange={e=>setF({...f,customerId:e.target.value})}/>
      <input placeholder="Address"    value={f.address}
             onChange={e=>setF({...f,address:e.target.value})}/>
      <select value={f.status} onChange={e=>setF({...f,status:e.target.value})}>
        {['Pending','Assigned','In Transit','Delivered'].map(s=>
          <option key={s} value={s}>{s}</option>)}
      </select>
      <button type="submit">Create</button>
    </form>
  );
}
